const pickCvss = (metrics) => {
  const order = [['cvssMetricV40','4.0'],['cvssMetricV31','3.1'],['cvssMetricV30','3.0'],['cvssMetricV2','2.0']];
  for (const [key, ver] of order) {
    const arr = metrics?.[key];
    if (Array.isArray(arr) && arr.length) {
      const m = arr.find(x => x.type === 'Primary') || arr[0];
      const d = m.cvssData || {};
      const score = d.baseScore;
      let sev = d.baseSeverity || m.baseSeverity;
      if (!sev && typeof score === 'number') sev = score >= 9 ? 'CRITICAL' : score >= 7 ? 'HIGH' : score >= 4 ? 'MEDIUM' : 'LOW';
      return { score, severity: sev ? String(sev).toUpperCase() : null, vector: d.vectorString || null, version: ver };
    }
  }
  return { score: null, severity: null, vector: null, version: null };
};
const cpeParts = (configurations) => {
  const vendors = new Set(), products = new Set();
  for (const c of configurations || []) for (const n of c.nodes || []) for (const m of n.cpeMatch || []) {
    const p = String(m.criteria || '').split(':');
    if (p.length > 4) { vendors.add(p[3]); products.add(p[4]); }
  }
  return { vendors: [...vendors], products: [...products] };
};

const cfg = $('Config').first().json;
const groupOf = (term) => {
  const t = String(term || '').toLowerCase();
  for (const [g, terms] of Object.entries(cfg.PRODUCT_GROUPS)) if (terms.some(x => x.toLowerCase() === t)) return g;
  return 'Other';
};

const wanted = $('Get unenriched KEV').all().map(i => i.json);
const byId = {};
for (const item of $input.all()) {
  const j = item.json || {};
  const v = (j.vulnerabilities || [])[0]?.cve;
  if (v?.id) byId[v.id] = { cv: pickCvss(v.metrics), desc: (v.descriptions || []).find(d => d.lang === 'en')?.value || '' };
}
const rows = wanted.map(w => {
  const n = byId[w.cve_id] || { cv: { score: null, severity: null, vector: null, version: null }, desc: '' };
  return { cve_id: w.cve_id, vendor: w.vendor, product: w.product, vuln_name: w.vuln_name, ransomware: w.ransomware,
    description: n.desc || w.description || '', matched_vendor: w.matched_vendor, product_group: w.product_group || groupOf(w.matched_vendor),
    cvss_score: n.cv.score, cvss_severity: n.cv.severity, cvss_vector: n.cv.vector, cvss_version: n.cv.version };
});
return [{ json: { rows, ids: rows.map(r => r.cve_id), nvd_found: Object.keys(byId).length } }];

const ids = $input.first().json.ids || [];
const chunk = (arr, n) => { const out = []; for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n)); return out; };
return chunk(ids, 100).map(c => ({ json: { cves: c.join(',') } }));

const rows = $('Parse NVD').first().json.rows;
const epss = {};
for (const item of $input.all()) for (const d of (item.json?.data || [])) epss[d.cve] = { epss: Number(d.epss), percentile: Number(d.percentile) };
for (const r of rows) { const e = epss[r.cve_id]; r.epss_score = e ? e.epss : null; r.epss_percentile = e ? e.percentile : null; }
return [{ json: { rows, ids: rows.map(r => r.cve_id), epss_found: Object.keys(epss).length } }];

const cfg = $('Config').first().json;
const rows = $input.first().json.rows;
if (!cfg.AI_ENABLED || rows.length === 0) return [{ json: { skip: true, prompt: 'Reply with {}' } }];
// one prompt per browser-release batch instead of per CVE
const seenBatch = new Set();
const picked = [];
for (const r of rows) {
  if (r.batch_key) { if (seenBatch.has(r.batch_key)) continue; seenBatch.add(r.batch_key); }
  picked.push(r);
  if (picked.length >= cfg.ENRICH_BATCH) break;
}
return picked.map(r => ({ json: { key: r.batch_key || r['cve_id'], prompt:
  `${cfg.AI_CONTEXT}\nYou write short threat-intel notes for our SOC analysts. Keep summary under 60 words and why under 45 words. Reply with JSON only, no markdown, exactly this shape: {"summary":"2 plain-English sentences: what the flaw is and what an attacker gains","why":"1 sentence: what we should do for clients (patch/mitigate/monitor) and how urgent"}\n\n` + `CVE: ${r.cve_id}\nVendor/product: ${r.vendor || r.matched_vendor || ''} ${r.product || ''}\nTitle: ${r.vuln_name || ''}\nCVSS: ${r.cvss_score ?? 'n/a'} ${r.cvss_severity || ''}  EPSS: ${r.epss_score ?? 'n/a'}  Ransomware use: ${r.ransomware || 'n/a'}\nDescription: ${(r.description || '').slice(0, 900)}` } }));

const parseAi = (item) => {
  try {
    const j = item.json || {};
    if (j.error || !j.content) return null;
    let text = (j.content || []).map(c => c.text || '').join('').trim();
    text = text.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    const start = text.indexOf('{'); const end = text.lastIndexOf('}');
    if (start < 0 || end < 0) return null;
    return JSON.parse(text.slice(start, end + 1));
  } catch { return null; }
};

const rows = $('Merge EPSS').first().json.rows;
const prep = $('Prep AI').all();
const byKey = {};
$input.all().forEach((item, i) => { const k = prep[i]?.json?.key; const p = k ? parseAi(item) : null; if (k && p) byKey[k] = p; });
let summarised = 0;
for (const r of rows) {
  const p = byKey[r.batch_key] || byKey[r['cve_id']];
  if (p) { r.ai_summary = String(p.summary || '').slice(0, 600); r.ai_reason = String(p.why || p.action || '').slice(0, 400); if (typeof p.relevant === 'boolean') r.ai_verdict = p.relevant; summarised++; }
}

return [{ json: { rows, summarised } }];

const rows = $input.first().json.rows;
const now = new Date().toISOString();
const out = rows.map(r => ({ cve_id: r.cve_id, cvss_score: r.cvss_score, cvss_severity: r.cvss_severity, cvss_vector: r.cvss_vector, cvss_version: r.cvss_version,
  epss_score: r.epss_score, epss_percentile: r.epss_percentile, product_group: r.product_group, ai_summary: r.ai_summary || null, ai_reason: r.ai_reason || null, enriched_at: now }));
return [{ json: { rows: out, count: out.length } }];
